diff --git a/src/jrd/replication/Applier.cpp b/src/jrd/replication/Applier.cpp
index a7b2eae6c27..ae67548534c 100644
--- a/src/jrd/replication/Applier.cpp
+++ b/src/jrd/replication/Applier.cpp
@@ -883,7 +883,7 @@ void Applier::executeSql(thread_db* tdbb,
 						 TraNumber traNum,
 						 unsigned charset,
 						 const string& sql,
-						 const MetaName& owner)
+						 const MetaName& ownerName)
 {
 	jrd_tra* transaction = NULL;
 	if (!m_txnMap.get(traNum, transaction))
@@ -897,11 +897,10 @@ void Applier::executeSql(thread_db* tdbb,
 	const auto dialect =
 		(dbb->dbb_flags & DBB_DB_SQL_dialect_3) ? SQL_DIALECT_V6 : SQL_DIALECT_V5;

-	UserId user(*attachment->att_user);
-	user.setUserName(owner);
-
 	AutoSetRestore<SSHORT> autoCharset(&attachment->att_charset, charset);
-	AutoSetRestore<UserId*> autoOwner(&attachment->att_user, &user);
+
+	UserId* const owner = attachment->getUserId(ownerName);
+	AutoSetRestore<UserId*> autoOwner(&attachment->att_ss_user, owner);

 	DSQL_execute_immediate(tdbb, attachment, &transaction,
 						   0, sql.c_str(), dialect,
diff --git a/src/jrd/scl.epp b/src/jrd/scl.epp
index 1c9835cd5d2..361589ba994 100644
--- a/src/jrd/scl.epp
+++ b/src/jrd/scl.epp
@@ -228,6 +228,10 @@ void SCL_check_access(thread_db* tdbb,
  **************************************/
 	SET_TDBB(tdbb);

+	// Allow the replicator any access to database, its permissions are already validated
+	if (tdbb->tdbb_flags & TDBB_replicator)
+		return;
+
 	const MetaName& userName = s_class->sclClassUser.second;

 	if (s_class && (s_class->scl_flags & SCL_corrupt))
@@ -286,6 +290,11 @@ void SCL_check_create_access(thread_db* tdbb, int type)
  *
  **************************************/
 	SET_TDBB(tdbb);
+
+	// Allow the replicator any access to database, its permissions are already validated
+	if (tdbb->tdbb_flags & TDBB_replicator)
+		return;
+
 	Jrd::Attachment* const attachment = tdbb->getAttachment();

 	// Allow the locksmith any access to database
